// ============================================================================
//  ETAPA A — Contactos ÚNICOS do WGT (a base do denominador)
// ============================================================================
// Para um teste rápido, poe LIMITE_TESTE = 50 (só verifica 50 contactos).
const LIMITE_TESTE = 0;   // 0 = TODOS

const vistos = new Map();
for (const it of $input.all()) {
  const arr = (it.json && Array.isArray(it.json.data)) ? it.json.data : [];
  for (const d of arr) {
    const c = d.contact || {};
    if (!c.id) continue;
    if (!vistos.has(c.id)) vistos.set(c.id, {
      contact_id: c.id,
      nome: String(c.name || '').trim(),
      email: String(c.email || '').trim().toLowerCase(),
      telefone: c.phone || '',
    });
  }
}
let lista = [...vistos.values()];
console.log('Negocios WGT lidos por pagina -> contactos WGT unicos: ' + lista.length);
if (LIMITE_TESTE > 0) { lista = lista.slice(0, LIMITE_TESTE); console.log('*** TESTE: so ' + lista.length + ' contactos ***'); }
return lista.map(v => ({ json: v }));

// ============================================================================
//  ETAPA B — Analisar histórico de cada contacto WGT: 1.o toque + ganhos fora
//  Denominador = 1.o negocio e WGT.  Numerador = desses, ganhou noutra origem.
//  Uma linha por PESSOA (agregada).
// ============================================================================
const WGT_ORIGINS = ['7403f4aa-7a29-4863-b44e-b4f5a6ae6094'];
const WGT = new Set(WGT_ORIGINS);

const origins = {};
for (const it of $('1. GET origens').all()) {
  const arr = (it.json && Array.isArray(it.json.data)) ? it.json.data : [];
  for (const o of arr) origins[o.id] = o.name || o.id;
}
const nome = (id) => origins[id] || id || '';
const isProduto = (id) => /^(IGT|FGRS)/i.test(nome(id));   // produto pago "real"
function ts(s){ const t=Date.parse(s); return isNaN(t)?Infinity:t; }
function dias(a,b){ const A=Date.parse(a),B=Date.parse(b); if(isNaN(A)||isNaN(B))return ''; return Math.round((B-A)/86400000); }

let verificados=0, semTimeline=0, originadosWGT=0, converteram=0, comProduto=0;
const destinos={};
const rows=[];

for (const it of $input.all()) {
  verificados++;
  const deals = (it.json && Array.isArray(it.json.data)) ? it.json.data : [];
  if (!deals.length) { semTimeline++; continue; }

  // 1.o negocio do contacto (across all)
  let earliest = deals[0];
  for (const d of deals) if (ts(d.created_at) < ts(earliest.created_at)) earliest = d;
  if (!WGT.has(earliest.origin_id)) continue;   // DENOMINADOR: 1.o toque tem de ser WGT
  originadosWGT++;

  const won = deals.filter(d => d.status === 'WON' && !WGT.has(d.origin_id));
  if (!won.length) continue;                     // originado mas nao converteu fora
  converteram++;

  const c = earliest.contact || (deals.find(d=>d.contact&&d.contact.name)||{}).contact || {};
  const entrada = earliest.created_at;
  won.sort((a,b)=>ts(a.won_at||a.created_at)-ts(b.won_at||b.created_at));
  const funis = [...new Set(won.map(w=>nome(w.origin_id)))];
  const produtos = [...new Set(won.filter(w=>isProduto(w.origin_id)).map(w=>nome(w.origin_id)))];
  won.forEach(w=>{ destinos[w.origin_id]=(destinos[w.origin_id]||0)+1; });
  if (produtos.length) comProduto++;

  const moedas = [...new Set(won.map(w=>w.currency).filter(Boolean))];
  const valorEur = won.filter(w=>w.currency==='EUR' && typeof w.value==='number').reduce((a,w)=>a+w.value,0);
  const primeiro = won[0].won_at || won[0].created_at;
  const ultimo = won[won.length-1].won_at || won[won.length-1].created_at;
  const suspeita = won.some(w=>{ const dd=dias(entrada, w.won_at||w.created_at); return dd!=='' && dd<=0; });

  rows.push({
    contacto_id: c.id || '',
    nome: String(c.name||'').trim(),
    email: String(c.email||'').trim().toLowerCase(),
    telefone: c.phone || '',
    data_entrada_wgt: entrada,
    n_ganhos_fora: won.length,
    funis_ganhos: funis.join(' | '),
    ganhou_produto_real: produtos.length ? 'SIM' : 'NAO',
    produtos_reais: produtos.join(' | '),
    valor_ganhos_eur: Math.round(valorEur*100)/100,
    moedas: moedas.join('|'),
    primeiro_ganho: primeiro,
    ultimo_ganho: ultimo,
    dias_ate_1o_ganho: dias(entrada, primeiro),
    total_negocios_contacto: deals.length,
    flag_importacao_suspeita: suspeita ? 'SIM' : '',
  });
}

const taxa = originadosWGT ? (100*converteram/originadosWGT) : 0;
const suspeitas = rows.filter(r=>r.flag_importacao_suspeita==='SIM').length;
console.log('==================== CONVERSAO CRUZADA WGT (v2) ====================');
console.log('Contactos WGT verificados: ' + verificados + ' | sem historico (falhas): ' + semTimeline);
console.log('>> DENOMINADOR - originados no WGT (1.o negocio = WGT): ' + originadosWGT);
console.log('>> NUMERADOR   - desses, converteram noutra origem: ' + converteram);
console.log('>> TAXA DE CONVERSAO CRUZADA: ' + taxa.toFixed(1) + '%');
console.log('   dos convertidos, com PRODUTO real (IGT/FGRS): ' + comProduto);
console.log('   linhas (1 por pessoa): ' + rows.length + ' | flags suspeitas: ' + suspeitas);
console.log('   destinos: ' + (Object.entries(destinos).sort((a,b)=>b[1]-a[1]).map(([k,v])=>nome(k)+'='+v).join(' | ')||'-'));

if (!rows.length) return [{ json: { nome:'SEM CONVERSOES', contacto_id:'', email:'', telefone:'', data_entrada_wgt:'', n_ganhos_fora:'', funis_ganhos:'', ganhou_produto_real:'', produtos_reais:'', valor_ganhos_eur:'', moedas:'', primeiro_ganho:'', ultimo_ganho:'', dias_ate_1o_ganho:'', total_negocios_contacto:'', flag_importacao_suspeita:'' } }];
return rows.map(r=>({json:r}));
